package mx.siabuc.helpdesk;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.assertj.core.api.Assertions.assertThat;
class InstallmentIntegrationIT extends ApiIntegrationSupport {
 @Autowired JdbcTemplate db;
 static LocalDate today(){return LocalDate.now(ZoneId.of("America/Mexico_City"));}
 static Map<String,Object> payload(long policy,String amount,LocalDate due){return Map.of("requestId",UUID.randomUUID().toString(),"policyId",policy,"dueOn",due.toString(),"amount",new BigDecimal(amount),"description","Compromiso acordado con la biblioteca");}
 private long policy(long institution,String amount)throws Exception{return success(admin.post("/policies",PolicyIntegrationIT.policyPayload(institution,amount,600,300))).path("policy").path("id").asLong();}
 private long create(long policy,String amount)throws Exception{return success(admin.post("/installments",payload(policy,amount,today().plusDays(5)))).path("installment").path("id").asLong();}
 private long payment(long institution,long policy,String amount)throws Exception{var p=new LinkedHashMap<>(PaymentIntegrationIT.paymentPayload(institution,0,0));p.put("policyId",policy);p.put("amount",new BigDecimal(amount));return success(admin.post("/payments",p)).path("id").asLong();}
 private Client billing()throws Exception{String u=unique("schedulebilling");success(admin.post("/users",Map.of("username",u,"displayName","Cobranza","password",PASSWORD,"role","BILLING","active",true,"email","schedule@example.test")));return login(u,PASSWORD);}
 @Test void planIsExactBoundedIdempotentAndNeverCreditsOrCreatesPayments()throws Exception{long institution=institution(10,20),policy=policy(institution,"100.03");var b=billing();var request=payload(policy,"33.34",today());long id=success(b.post("/installments",request)).path("installment").path("id").asLong();assertThat(success(b.post("/installments",request)).path("installment").path("id").asLong()).isEqualTo(id);create(policy,"33.34");create(policy,"33.35");assertStatus(b.post("/installments",payload(policy,"0.01",today())),409);var altered=new LinkedHashMap<>(request);altered.put("amount",new BigDecimal("33.33"));assertStatus(b.post("/installments",altered),409);assertThat(db.queryForObject("SELECT SUM(amount) FROM policy_installments WHERE policy_id=?",BigDecimal.class,policy)).isEqualByComparingTo("100.03");assertThat(db.queryForObject("SELECT COUNT(*) FROM payments WHERE institution_id=?",Long.class,institution)).isZero();assertBalance(institution,0,10,0,20);}
 @Test void allocationsSplitExistingPaymentAndRejectOveruseOrForeignPolicy()throws Exception{long institution=institution(0,0),policy=policy(institution,"100"),one=create(policy,"60"),two=create(policy,"40"),paid=payment(institution,policy,"70");success(admin.post("/installments/"+one+"/allocations",Map.of("paymentId",paid,"amount",new BigDecimal("50"))));success(admin.post("/installments/"+one+"/allocations",Map.of("paymentId",paid,"amount",new BigDecimal("50"))));assertStatus(admin.post("/installments/"+one+"/allocations",Map.of("paymentId",paid,"amount",new BigDecimal("51"))),409);assertStatus(admin.post("/installments/"+two+"/allocations",Map.of("paymentId",paid,"amount",new BigDecimal("21"))),409);success(admin.post("/installments/"+two+"/allocations",Map.of("paymentId",paid,"amount",new BigDecimal("20"))));long other=institution(0,0),otherPolicy=policy(other,"100"),foreign=payment(other,otherPolicy,"50");assertStatus(admin.post("/installments/"+one+"/allocations",Map.of("paymentId",foreign,"amount",BigDecimal.ONE)),409);assertThat(success(admin.get("/installments/"+one)).path("allocations")).hasSize(1);assertThat(db.queryForObject("SELECT COUNT(*) FROM payments WHERE institution_id=?",Long.class,institution)).isEqualTo(1);assertBalance(institution,0,0,0,0);}
 @Test void voidedPaymentsReopenCommitmentAndRemovingAllocationKeepsHistory()throws Exception{long institution=institution(0,0),policy=policy(institution,"100"),id=create(policy,"100"),paid=payment(institution,policy,"100");var linked=success(admin.post("/installments/"+id+"/allocations",Map.of("paymentId",paid,"amount",new BigDecimal("100"))));long allocation=linked.path("allocations").get(0).path("id").asLong();assertThat(linked.path("installment").path("status").asText()).isEqualTo("PAID");assertStatus(admin.post("/installments/"+id+"/cancel",Map.of("reason","Cambiar fecha")),409);success(admin.post("/payments/"+paid+"/void",Map.of("reason","Pago duplicado")));var reopened=success(admin.get("/installments/"+id));assertThat(reopened.path("installment").path("pendingAmount").decimalValue()).isEqualByComparingTo("100");assertThat(reopened.path("allocations").get(0).path("paymentVoided").asBoolean()).isTrue();assertStatus(admin.post("/installments/"+id+"/allocations",Map.of("paymentId",paid,"amount",new BigDecimal("100"))),409);success(admin.post("/installments/"+id+"/allocations/"+allocation+"/remove",Map.of("reason","Conservar referencia de pago anulado")));var cancelled=success(admin.post("/installments/"+id+"/cancel",Map.of("reason","Programar nuevo acuerdo")));assertThat(cancelled.path("installment").path("status").asText()).isEqualTo("CANCELLED");assertThat(cancelled.path("history")).hasSize(4);assertThat(cancelled.path("allocations")).hasSize(1);create(policy,"100");}
 @Test void contractAmountCannotChangeWhileScheduleExistsAndCanceledPolicyStopsCollection()throws Exception{long institution=institution(0,0);var input=PolicyIntegrationIT.policyPayload(institution,"100",600,300);long policy=success(admin.post("/policies",input)).path("policy").path("id").asLong(),id=create(policy,"60");input.put("agreedAmount",new BigDecimal("50"));assertStatus(admin.put("/policies/"+policy,input),409);success(admin.post("/installments/"+id+"/cancel",Map.of("reason","Renegociación")));success(admin.put("/policies/"+policy,input));long next=create(policy,"50");success(admin.post("/policies/"+policy+"/cancel",Map.of("reason","No se contratará")));assertThat(success(admin.get("/installments/"+next)).path("installment").path("pendingAmount").decimalValue()).isZero();assertStatus(admin.post("/installments",payload(policy,"1",today())),409);}
 @Test void remindersAreConfigurableDeduplicatedPersonallyReadAndIndependentOfMail()throws Exception{long institution=institution(0,0),policy=policy(institution,"100");long id=success(admin.post("/installments",payload(policy,"30",today().minusDays(1)))).path("installment").path("id").asLong();success(admin.put("/installments/settings",Map.of("enabled",false,"daysBeforeDue",7)));success(admin.post("/installments/scan",Map.of()));assertThat(db.queryForObject("SELECT COUNT(*) FROM installment_notices WHERE installment_id=?",Long.class,id)).isZero();success(admin.put("/installments/settings",Map.of("enabled",true,"daysBeforeDue",7)));success(admin.post("/installments/scan",Map.of()));success(admin.post("/installments/scan",Map.of()));assertThat(db.queryForObject("SELECT COUNT(*) FROM installment_notices WHERE installment_id=?",Long.class,id)).isEqualTo(1);long notice=db.queryForObject("SELECT id FROM installment_notices WHERE installment_id=?",Long.class,id);success(admin.post("/installments/notices/"+notice+"/read",Map.of()));var billing=billing();assertThat(db.queryForObject("SELECT COUNT(*) FROM installment_notice_reads WHERE notice_id=?",Long.class,notice)).isEqualTo(1);success(billing.post("/installments/notices/"+notice+"/read",Map.of()));assertThat(db.queryForObject("SELECT COUNT(*) FROM installment_notice_reads WHERE notice_id=?",Long.class,notice)).isEqualTo(2);assertStatus(admin.put("/installments/settings",Map.of("enabled",true,"daysBeforeDue",366)),400);}
 @Test void concurrentScheduleCreationCannotExceedContract()throws Exception{long institution=institution(0,0),policy=policy(institution,"100");Client a=billing(),b=billing();a.refreshCsrf();b.refreshCsrf();var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var one=pool.submit(()->{start.await(20,TimeUnit.SECONDS);return a.post("/installments",payload(policy,"70",today()));});var two=pool.submit(()->{start.await(20,TimeUnit.SECONDS);return b.post("/installments",payload(policy,"70",today()));});start.countDown();var statuses=List.of(one.get(40,TimeUnit.SECONDS).getResponse().getStatus(),two.get(40,TimeUnit.SECONDS).getResponse().getStatus());assertThat(statuses).containsExactlyInAnyOrder(200,409);}finally{start.countDown();pool.shutdownNow();}assertThat(db.queryForObject("SELECT SUM(amount) FROM policy_installments WHERE policy_id=?",BigDecimal.class,policy)).isEqualByComparingTo("70");}
 @Test void invalidAmountsAndCsrfAreRejectedWithoutRows()throws Exception{long institution=institution(0,0),policy=policy(institution,"100");for(String v:List.of("0","-0.01","1.001","1000000000"))assertStatus(admin.post("/installments",payload(policy,v,today())),400);assertStatus(admin.raw("POST","/installments",payload(policy,"10",today()),false),403);assertThat(db.queryForObject("SELECT COUNT(*) FROM policy_installments WHERE policy_id=?",Long.class,policy)).isZero();}
}
